import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPoppins = makeLoadFont('Poppins');

// Library: none — native spring for a bouncy pop-up and SVG for the precise shape

// Module-level font loading ensures readiness before frame 0
const { fontFamily: poppinsFamily } = loadPoppins();



export type SpeechBubblePopProps = Record<string, any>;

const SpeechBubblePop: React.FC<SpeechBubblePopProps> = ({
  backgroundColor = "#04143a",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "GET STARTED",
  bubbleColor = "#17c3a7",
  textColor = "#ffffff",
  shadowColor = "#020a1c",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Base scale factor responsive to canvas
  const s = Math.min(width, height) / 1080;

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing
  const startFrame = 10;
  
  // Spring calculates the scale-up from 0 to 1
  const popScale = spring({
    fps,
    frame: frame - startFrame,
    config: {
      damping: 12,
      stiffness: 140,
      mass: 0.8,
    },
  });

  // A subtle floating/bobbing motion applied after the entrance completes
  const floatY = interpolate(
    frame - startFrame,
    [0, 30], // Smoothly ramp up the float amplitude as the spring finishes
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  ) * Math.sin((frame - startFrame) / 20) * (15 * s);

  // Rule 6: Fully hidden before entrance
  const isVisible = frame >= startFrame;

  // Internal SVG Geometry proportions
  const bubbleW = 1200;
  const bubbleH = 350;
  const tailHeight = 100;
  const totalH = bubbleH + tailHeight;

  // Helper to render the shape (used for both main body and shadow)
  const renderBubbleShape = (fillColor: string) => (
    <g fill={fillColor} style={{ transition: "none" }}>
      {/* Main Pill Shape */}
      <rect x="0" y="0" width={bubbleW} height={bubbleH} rx={bubbleH / 2} />
      {/* Downward pointing tail. Y=348 ensures a slight overlap to prevent a rendering seam */}
      <polygon points="530,348 650,348 570,450" />
    </g>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          opacity: isVisible ? 1 : 0,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "relative",
            width: bubbleW * s,
            height: totalH * s,
            // Scale and float
            transform: `scale(${popScale}) translateY(${floatY}px)`,
            // Anchor transformation to the bottom center (tip of the tail)
            transformOrigin: "50% 100%",
            transition: "none",
          }}
        >
          {/* Shadow Layer */}
          <svg
            width="100%"
            height="100%"
            viewBox={`0 0 ${bubbleW} ${totalH}`}
            style={{
              position: "absolute",
              top: 25 * s,
              left: 15 * s,
              transition: "none",
            }}
          >
            {renderBubbleShape(shadowColor)}
          </svg>

          {/* Main Bubble Layer */}
          <svg
            width="100%"
            height="100%"
            viewBox={`0 0 ${bubbleW} ${totalH}`}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              transition: "none",
            }}
          >
            {renderBubbleShape(bubbleColor)}
          </svg>

          {/* Text Container */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: bubbleH * s, // Center text strictly within the pill, ignoring the tail
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: poppinsFamily,
                fontWeight: 900,
                fontSize: 140 * s,
                color: textColor,
                letterSpacing: "0.03em",
                lineHeight: 1,
                marginTop: 10 * s, // Optical baseline adjustment for heavy uppercase sans
                transition: "none",
                whiteSpace: "nowrap",
              }}
            >
              {text}
            </span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SpeechBubblePop;